function minOperations(k) {
  let best = k - 1;
  for (let value = 1; value <= k; value++) {
    const increases = value - 1;
    const copies = Math.ceil(k / value);
    const duplicates = copies - 1;
    best = Math.min(best, increases + duplicates);
  }
  return best;
}

