function minOperations(k) {
  // Try every total t = 0, 1, 2, ... and every split into a increments and d duplications.
  for (let total = 0; ; total++) {
    for (let a = 0; a <= total; a++) {
      const d = total - a;
      if ((a + 1) * (d + 1) >= k) return total;
    }
  }
}

