function generate(rand, size) {
  if (size === 'large') return [50000 + Math.floor(rand() * 50001)];
  const pick = rand();
  if (pick < 0.15) return [1 + Math.floor(rand() * 4)];
  if (pick < 0.35) {
    const side = 1 + Math.floor(rand() * 15);
    return [side * side + Math.floor(rand() * 3) - 1 || 1];
  }
  return [1 + Math.floor(rand() * 400)];
}
